<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/session.php'; require_once __DIR__ . '/includes/helpers.php'; require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/csrf.php'; require_once __DIR__ . '/includes/booking.php';
require_login(); if (empty($_SESSION['booking']['resource_id']) || empty($_SESSION['booking']['booking_date']) || empty($_SESSION['booking']['start_time'])) redirect('booking-step-1.php');
$booking = $_SESSION['booking']; $statement = db()->prepare('SELECT * FROM resources WHERE id = ? AND is_active = 1'); $statement->execute([(int) $booking['resource_id']]); $resource = $statement->fetch(); if (!$resource) redirect('booking-step-1.php'); $extras = booking_extras(); $extra_ids = array_map('intval', (array) ($_POST['extra_ids'] ?? $_SESSION['booking']['extra_ids'] ?? [])); $coupon_code = trim((string) ($_POST['coupon_code'] ?? $_SESSION['booking']['coupon_code'] ?? '')); $calculation = calculate_booking($resource, $extra_ids, $coupon_code);
